#' @title Generic S3 method for creating an initial values function
#'
#' @description Called by bmm() to create an initfun for models that require
#'   initial values to properly start sampling
#'
#' @param model The `bmmodel` object for with an initfun should be created
#' @param data The user supplied data.frame used to fit the model
#' @param formula The `brmsformula` generated by `configure_model` including the
#'   family for the `bmmodel` to be estimated.
#' @param prior The `brmsprior` the model will be fitted with. Parameters it
#'   holds constant are absent from the Stan code and get no initial value.
#' @param ... The arguments of [brms::brm()] besides formula, data and prior
#'   that change the Stan data or code (`data2`, `knots`,
#'   `drop_unused_levels`), passed on to [brms::standata()] and
#'   [brms::stancode()].
#'
#' @return An initfun with no arguments that generates
#'   inital values suitable for the STAN parameters generated by the respective
#'   model call
#'
#' @export
#' @keywords internal developer
create_initfun <- function(model, data, formula, prior = NULL, ...) {
  UseMethod("create_initfun")
}

# Every Stan parameter gets a value: random-effects parameters a tight start
# (small sd, z near zero, identity correlations), population-level parameters a
# draw from the model's init_ranges through the link, and everything else what
# brm(init = 1) would draw. A partial list would make cmdstanr fill the gaps at
# radius 2 and say so
#' @export
create_initfun.default <- function(model, data, formula, prior = NULL, ...) {
  standata_list <- standata(formula, data, formula$family, prior = prior, ...)
  stan_code <- stancode(formula, data, formula$family, prior = prior, ...)
  stanpars_list <- extract_parameter_dimensions(extract_stan_blocks(stan_code)$parameters)
  new_initfun(stanpars_list, standata_list, model)
}

# brms stores the init function in the fit, and saveRDS() writes the function's
# environment with it. A closure made in the method would keep the method's
# frame, whose generic call environment leads back to the frames of bmm() or
# update(), with the data and the fitted model. Made here, it keeps only what it
# reads. The arguments are forced first, because an unforced promise would hold
# on to the caller's frame until the function's first call
new_initfun <- function(stanpars_list, standata_list, model) {
  force(stanpars_list)
  force(standata_list)
  force(model)

  function() {
    stan_names <- names(stanpars_list)
    inits <- lapply(stan_names, function(spar) {
      init_stan_param(spar, stanpars_list[[spar]], model, standata_list)
    })
    names(inits) <- stan_names
    inits[!vapply(inits, is.null, logical(1))]
  }
}

# A parameter whose size cannot be resolved from the Stan data is left to the
# sampler, so that the rest of the list still reaches it
init_stan_param <- function(spar, spec, model, standata_list) {
  dim <- resolve_stan_dim(spec$dims, standata_list)
  if (anyNA(dim)) {
    return(NULL)
  }
  init_ranef_param(spar, spec$types, dim, model, standata_list) %||%
    init_special_coef_param(spar, spec$types, dim, model, standata_list) %||%
    init_fixef_param(spar, spec$types, dim, model, standata_list) %||%
    init_default_param(spec, dim, standata_list)
}


match_stan_to_model_par <- function(spar, model_pars) {
  # brms leaves the intercept and coefficients of the main dpar unsuffixed
  if (spar %in% c("Intercept", "b")) {
    return("mu")
  }
  parameter <- model_pars[unlist(lapply(
    paste0("(^|_)", model_pars, "(_|$)"), grepl, x = spar
  ))]
  if (length(parameter) > 1) {
    parameter <- parameter[which.max(nchar(parameter))]
  }
  if (length(parameter) == 0) {
    parameter <- strsplit(spar, "_")[[1]][1]
  }
  parameter
}


# Helper functions for initializing different parameter types ----------------

# brms names the random-effects parameters by their role, not by the model
# parameter; a constant on one coefficient makes brms replace a vector by
# per-coefficient scalars named par_<vector>_<index>. The penalized part of an
# s() term is a random effect too (sds_*, zs_*)
init_ranef_param <- function(spar, types, dim, model, standata_list) {
  if (any(types %in% c("cholesky_factor_corr", "cholesky_factor_cov", "cov_matrix", "corr_matrix"))) {
    return(init_identity(types, dim))
  }
  if (grepl("^(par_)?sds?_", spar)) {
    shrink <- sd_entry_shrink(spar, model, standata_list)
    if (length(shrink) != dim[1]) {
      shrink <- 1
    }
    return(init_array(runif(prod(dim), min = 0.05, max = 0.1) * rep_len(shrink, prod(dim)), types, dim))
  }
  if (grepl("^zs?_", spar)) {
    return(init_array(runif(prod(dim), min = -0.5, max = 0.5), types, dim))
  }
  NULL
}

# A coefficient moves its parameter by its value times the column it
# multiplies, on the link scale. Drawn without regard to either, a random slope
# on a trial number (1 to 40) moves it by up to 2, and an SD of 0.05 on the
# identity link is several times the whole start range of a parameter the data
# bound (cswald's ndt below a 0.03 s response is 0.012-0.018). Either puts some
# rows past the bound, where the likelihood is -Inf. The draw is shrunk by the
# largest absolute value of the column and by the width of the parameter's init
# range on the link scale, each only where it exceeds 1 or falls short of it,
# so a unit column on a range wider than 1 starts as before
coef_shrink <- function(parameter, columns, model) {
  if (is.null(parameter)) {
    return(1)
  }
  link <- init_link(model$links[[parameter]])
  range <- representable_range(model$init_ranges[[parameter]], link)
  width <- if (is.null(range)) 1 else abs(diff(link_transform(range, link)))
  reach <- abs(as.numeric(unlist(columns)))
  min(1, width, na.rm = TRUE) / max(1, reach[is.finite(reach)])
}

# One factor per entry of an SD vector, in entry order: sd_<id> (whose by
# matrix has one row per entry), its per-entry scalars par_sd_<id>_<k>, and
# sds_<par>_<i> of an s() term, whose entry j scales the columns
# Zs_<par>_<i>_<j> (Zs_<i>_<j> on the main dpar)
sd_entry_shrink <- function(spar, model, standata_list) {
  if (startsWith(spar, "sds_")) {
    term <- sub("^sds_", "", spar)
    parameter <- sub("_?[0-9]+$", "", term)
    columns <- paste0("Zs_", term, "_", seq_len(standata_list[[paste0("nb_", term)]] %||% 0))
    return(vapply(columns, function(column) {
      coef_shrink(if (nzchar(parameter)) parameter else "mu", standata_list[[column]], model)
    }, numeric(1), USE.NAMES = FALSE))
  }
  id <- sub("^(par_)?sd_([0-9]+).*$", "\\2", spar)
  entries <- if (startsWith(spar, "par_")) {
    as.integer(sub(".*_", "", spar))
  } else {
    seq_len(standata_list[[paste0("M_", id)]] %||% 0)
  }
  owners <- ranef_column_owners(id, model, standata_list)
  vapply(entries, function(k) {
    own <- owners[owners$entry %in% k, , drop = FALSE]
    if (nrow(own) == 0) {
      return(1)
    }
    coef_shrink(own$parameter[1], standata_list[own$column], model)
  }, numeric(1))
}

# brms names the column of entry k of group term <id> Z_<id>_<par>_<k>, or
# Z_<id>_<k> on the main dpar, and an mm() term appends _<member>; k counts
# across every parameter the term holds. Parameter names may end in digits
# (mu1), so the owner is found by matching the names the model and the Stan
# data know, not by splitting at underscores. A column whose name does not
# parse has entry NA and is not read
ranef_column_owners <- function(id, model, standata_list) {
  prefix <- paste0("Z_", id, "_")
  columns <- names(standata_list)[startsWith(names(standata_list), prefix)]
  rest <- substring(columns, nchar(prefix) + 1)
  known <- union(names(model$parameters), sub("^K_", "", grep("^K_", names(standata_list), value = TRUE)))
  parameter <- vapply(rest, function(r) {
    owner <- known[startsWith(r, paste0(known, "_"))]
    if (length(owner)) owner[which.max(nchar(owner))] else "mu"
  }, character(1), USE.NAMES = FALSE)
  index <- ifelse(parameter == "mu", rest, substring(rest, nchar(parameter) + 2))
  parsed <- grepl("^[0-9]+(_[0-9]+)?$", index)
  entry <- rep(NA_integer_, length(index))
  entry[parsed] <- as.integer(sub("_.*$", "", index[parsed]))
  data.frame(column = columns, parameter = parameter, entry = entry)
}

# The linear part of an s() term (bs_<par>) and the coefficients of special
# terms such as mo() (bsp_<par>; bs and bsp on the main dpar) have no range of
# their own and start near zero, shrunk as random-effects SDs are. mo()
# multiplies its coefficient by up to the number of categories minus one (Jmo)
# of each of its variables, and by any covariate it interacts with (Csp); the
# Stan data do not say which variables belong to which coefficient, so every
# coefficient is shrunk by all of them together, which can only shrink it more
init_special_coef_param <- function(spar, types, dim, model, standata_list) {
  if (!grepl("^bsp?(_|$)", spar)) {
    return(NULL)
  }
  suffix <- sub("^bsp?_?", "", spar)
  parameter <- if (nzchar(suffix)) suffix else "mu"
  data_name <- function(prefix) paste0(prefix, if (nzchar(suffix)) "_", suffix)
  shrink <- if (startsWith(spar, "bsp")) {
    covariates <- standata_list[grep(paste0("^", data_name("Csp"), "_[0-9]+$"), names(standata_list))]
    coef_shrink(parameter, prod(standata_list[[data_name("Jmo")]]) * max(1, abs(as.numeric(unlist(covariates)))), model)
  } else {
    columns <- standata_list[[data_name("Xs")]]
    if (is.null(columns)) {
      coef_shrink(parameter, NULL, model)
    } else {
      apply(as.matrix(columns), 2, function(column) coef_shrink(parameter, column, model))
    }
  }
  init_array(runif(prod(dim), min = -0.1, max = 0.1) * rep_len(shrink, prod(dim)), types, dim)
}

# A matrix declaration names its size once; gr(by = ) declares an array of
# them, one per level of the by variable
init_identity <- function(types, dim) {
  identity <- diag(nrow = dim[length(dim)])
  if (!"array" %in% types) {
    return(identity)
  }
  levels <- dim[-length(dim)]
  array(rep(identity, each = prod(levels)), dim = c(levels, dim(identity)))
}

# brms names the coefficients of a parameter b_<par> (b for the main dpar) and
# replaces them by per-coefficient scalars par_b_<par>_<index> when a constant
# holds some of them fixed; a scalar gets the value its position in the vector
# would get
init_fixef_param <- function(spar, types, dim, model, standata_list) {
  index <- if (grepl("^par_b_", spar)) as.integer(sub(".*_", "", spar))
  stan_par <- if (is.null(index)) spar else sub("^par_(.*)_[0-9]+$", "\\1", spar)
  parameter <- match_stan_to_model_par(stan_par, names(model$parameters))
  link <- init_link(model$links[[parameter]])
  init_range <- representable_range(model$init_ranges[[parameter]], link)
  if (is.null(init_range)) {
    return(NULL)
  }
  from_range <- function(n) link_transform(runif(n, min = init_range[1], max = init_range[2]), link)
  if (startsWith(stan_par, "Intercept")) {
    return(from_range(1))
  }
  if (!grepl("^b(_|$)", stan_par)) {
    return(NULL)
  }
  X <- standata_list[[sub("^b", "X", stan_par)]]
  if (is.null(X)) {
    return(NULL)
  }

  values <- range_coefficients(
    X, from_range(1), centered = !is.null(standata_list[[sub("^b", "Kc", stan_par)]])
  )
  init_array(if (is.null(index)) values else values[index], types, dim)
}

# The coefficients that put the linear predictor at `target` on every row of
# brms's own design matrix: the least-squares solution of D b = target, where D
# is the design the Stan program uses -- a separate intercept beside the centred
# columns where brms records the centring as Kc_<par>, the matrix itself
# otherwise. Cell means, treatment contrasts, interactions, a 0 + Intercept term
# and dropped levels all follow from the one solve, and a design that cannot
# reach the target exactly gets the closest it can. Aliased columns solve to NA
# and start at zero, and so does every column of a design that carries a
# non-finite value, which qr() rejects outright -- a predictor with an Inf in it
# is Stan's error to report, not this function's
range_coefficients <- function(X, target, centered) {
  if (centered) {
    X <- cbind(Intercept = 1, scale(X[, -1, drop = FALSE], scale = FALSE))
  }
  values <- if (all(is.finite(X))) qr.coef(qr(X), rep(target, nrow(X))) else rep(NA_real_, ncol(X))
  values[is.na(values)] <- 0
  unname(if (centered) values[-1] else values)
}

# The likelihood of a response time model is -Inf wherever ndt >= rt, so the
# start of ndt comes from the fastest response; a fixed range lies above it for
# fast data. rt = 0 is left out: a censored response there never binds, and a
# response of 1 there cannot be fitted with any positive ndt
.ndt_init_range <- function(rt) {
  c(0.4, 0.6) * min(rt[rt > 0])
}

# init_ranges of softmax parameters are declared on the sampling scale, as
# a softmax weight has no native value of its own
init_link <- function(link) {
  if (identical(link, "softmax")) "identity" else link
}

# init_ranges are written for a parameter's default link, and a link set by the
# user can exclude part of them (a softplus criterion cannot start at -0.3),
# which link_transform() would turn into NaN. Draws are confined to the part of
# the range the link can represent. What is left of a range may be nothing or a
# single point, which would start every chain at the same value (or at the
# link's infinite edge, as log(0)); either is dropped, and the parameter gets
# the default draw, as without an init_range
representable_range <- function(init_range, link) {
  if (is.null(init_range)) {
    return(NULL)
  }
  domain <- .link_ranges[[link %||% "identity"]]
  lower <- max(init_range[1], domain[1])
  upper <- min(init_range[2], domain[2])
  if (lower >= upper) NULL else c(lower, upper)
}

# Stan draws initial values uniformly on the unconstrained scale and maps them
# through the parameter's declared bounds; with a radius of 1 this is exactly
# what brm(init = 1) does. Returns NULL for the types whose transform is not
# reimplemented here (ordered, unit_vector, ...) and for bounds that cannot be
# resolved to a number, leaving those parameters to the sampler
init_default_param <- function(spec, dim, standata_list) {
  if (identical(spec$type, "simplex")) {
    return(init_array(init_simplex(runif(dim - 1, min = -1, max = 1), dim), spec$types, dim))
  }
  if (!spec$type %in% c("real", "vector", "row_vector", "matrix")) {
    return(NULL)
  }
  lower <- resolve_stan_bound(spec$bounds$lower, standata_list, -Inf)
  upper <- resolve_stan_bound(spec$bounds$upper, standata_list, Inf)
  if (is.na(lower) || is.na(upper)) {
    return(NULL)
  }

  raw <- runif(prod(dim), min = -1, max = 1)
  value <- if (is.infinite(lower) && is.infinite(upper)) {
    raw
  } else if (is.infinite(upper)) {
    lower + exp(raw)
  } else if (is.infinite(lower)) {
    upper - exp(raw)
  } else {
    lower + (upper - lower) * plogis(raw)
  }
  init_array(value, spec$types, dim)
}

# Stan's stick-breaking transform of a simplex: each break is a logistic draw
# shifted so that a zero draw leaves equal shares to every remaining element
init_simplex <- function(raw, n) {
  shares <- numeric(n)
  left <- 1
  for (k in seq_len(n - 1)) {
    shares[k] <- left * stats::plogis(raw[k] - log(n - k))
    left <- left - shares[k]
  }
  shares[n] <- left
  shares
}

# rstan reads a bare length-1 numeric as a scalar and stops with "no more
# scalars to read" at a size-1 vector; cmdstanr repairs the list, rstan does
# not. The parser gives a real the dimension 1, which an array of reals drops
init_array <- function(values, types, dim) {
  if (identical(types, "real")) {
    return(values)
  }
  array(values, dim = if ("real" %in% types) dim[-length(dim)] else dim)
}

# Stan declarations carry their dimensions as a literal (scalars), as the name
# of a variable in the data block, or as an element of a data array (Jmo_c[1]
# for mo(), knots_kappa_1[1] for s()); NA marks a dimension that is none of these
resolve_stan_dim <- function(dims, standata_list) {
  vapply(dims, function(d) {
    literal <- suppressWarnings(as.numeric(d))
    if (!is.na(literal)) {
      return(literal)
    }
    name <- sub("\\[.*$", "", d)
    index <- if (grepl("[", d, fixed = TRUE)) sub("^[^\\[]*\\[([0-9]+)\\]$", "\\1", d) else "1"
    as.numeric(standata_list[[name]])[suppressWarnings(as.integer(index))]
  }, numeric(1), USE.NAMES = FALSE)
}

# Bounds are parsed as strings and may be numbers or the names of data
# variables; NA marks a bound that is neither
resolve_stan_bound <- function(value, standata_list, default) {
  if (is.null(value)) {
    return(default)
  }
  number <- suppressWarnings(as.numeric(value))
  if (!is.na(number)) {
    return(number)
  }
  from_data <- standata_list[[value]]
  if (is.numeric(from_data) && length(from_data) == 1) from_data else NA_real_
}
